import json,math,random,statistics,datetime
from pathlib import Path
P=Path(__file__).resolve().parent
r=json.loads((P/'audit_results.json').read_text());b=r['base'];rng=random.Random(777);days=list(b['daily'].values());boot=sorted(sum(rng.choice(days) for _ in days) for _ in range(20000))
# All offsets restricted to UTC six-hour blocks with completed trades in every offset.
maps=[{x['signal']//21600:x for x in a['rows']} for a in r['offsets']];common=set.intersection(*(set(m) for m in maps));paired=[sum(m[k]['net'] for k in common) for m in maps]
errors=[]
old=json.loads((P.parent/'kalshi_full_review_2026_09_26/results/gold_perp_execution_challenge.json').read_text())
if abs(old['stress']-b['net'])>1e-8:errors.append('Prior result reproduction mismatch')
for group in ['offsets','delays','costs','controls']:
 for a in r[group]:
  prev=0
  for t in a['rows']:
   if t['entry_ts']<prev:errors.append('Overlapping positions')
   prev=t['exit_ts']
   if not t['signal']<t['entry_ts']<t['exit_ts']:errors.append('Chronology')
   if t['count']*t['entry']>50+1e-9:errors.append('Notional budget')
   if abs(t['net']-(t['gross']-t['fees']+t['funding']-t['stress_cost']))>1e-9:errors.append('Accounting')
book=json.loads((P/'data/book.json').read_text())['orderbook'];ask=min((float(p),float(n)) for p,n in book['asks']);bid=max((float(p),float(n)) for p,n in book['bids']);count=math.floor(50/ask[0])
v={'errors':errors,'prior_result_reproduced':not errors,'common_offset_blocks':len(common),'common_offset_net':paired,'day_bootstrap_95_total_interval':[boot[500],boot[19500]],'best_book_ask':ask,'best_book_bid':bid,'contracts_under_50':count}
(P/'validation.json').write_text(json.dumps(v,indent=2));assert not errors,errors
lines=['# Gold perpetual research — September 26, 2026','','## Decision','','Keep gold perpetual six-hour reversal as a research candidate, but do not treat it as a verified live edge. The original clock schedule remains profitable after realistic cost and delay challenges. However, moving its schedule by just a few hours loses money in half the variants. Recent days are also negative. This materially weakens the earlier broad-review shortlist recommendation. No live bot, orders or transfers were created.','','## Fixed strategy','','At 00:00, 06:00, 12:00 and 18:00 UTC compare the completed gold-perpetual midpoint against six hours earlier. Short a rise; buy a decline. Hold six hours. Require signal spread <=20bp and nonzero completed-hour volume. Size whole contracts to <=$50 notional within a hypothetical $100 account. Cross the bid/ask, charge 0.72bp taker fees per side using the earlier same-day authenticated fee receipt, include reported funding, and add at least one tick or 1bp per side. One-minute delayed entry and exit use minute-close quotes. This is price reversal, not a funding-income or gold-price forecasting model.','','## Reproduced core result','',f"September 11–25: {b['trades']} trades, {b['wins']} profitable ({b['wins']/b['trades']:.1%}); net ${b['net']:.4f}. Gross bid/ask P&L ${b['gross']:.4f}, fees ${b['fees']:.4f}, funding ${b['funding']:.4f}, extra execution cost ${sum(t['stress_cost'] for t in b['rows']):.4f}. About ${b['net']/b['trades']:.3f} per trade; no annualization.",'',f"Longs ${b['long_net']:+.2f}; shorts ${b['short_net']:+.2f}. Removing the best three trades leaves ${b['without_best_3_trades']:+.2f}; removing the best day leaves ${b['without_best_day']:+.2f}. Always-long on the same windows loses ${-r['controls'][0]['net']:.2f}; always-short loses ${-r['controls'][1]['net']:.2f}.",'',f"Observed minute-close equity drawdown ${b['minute_close_drawdown']:.2f}; worst observed open-trade P&L ${b['worst_open_trade']:.2f}. There are {b['missing_minute_marks']} unavailable/invalid minute marks inside the paths, so these are incomplete observed drawdowns, not maximum possible loss or a liquidation simulation.",'','## Clock sensitivity: the main weakness','','Each row independently runs the same rule with a different six-hour starting schedule. They overlap and are not independent samples. All use 60-second delays and 1bp extra cost on each leg.','','| UTC start offset | Trades | Net | Net on common blocks |','|---|---:|---:|---:|']
for a,pair in zip(r['offsets'],paired):lines.append(f"| +{a['offset']} hours | {a['trades']} | ${a['net']:+.2f} | ${pair:+.2f} |")
lines+=['',f"Common-block comparison retains {len(common)} six-hour blocks available in every schedule; it reduces missing-data composition differences but is a retrospective diagnostic, not a deployable filter. The original schedule was predeclared in the broad screen, but the strategy itself was selected from 128 candidates. These results must not be used to choose a newly best clock.",'','## Delay and cost challenges','','| Challenge | Trades | Net |','|---|---:|---:|']
for a in r['delays']:lines.append(f"| {a['delay']//60}-minute delay, 1bp each leg | {a['trades']} | ${a['net']:+.2f} |")
for a in r['costs'][1:]:lines.append(f"| 1-minute delay, {a['extra_bp_each_leg']}bp each leg | {a['trades']} | ${a['net']:+.2f} |")
lines+=['','Missing execution quotes omit two trades in the longer-delay variants. That is a replay limitation: a live system cannot retroactively skip an entry because its future exit quote is missing. It must handle outages and unwind risk. Baseline has zero missing entry/exit quotes.','','## Recency and uncertainty','',f"Last three original sample days total ${sum(list(b['daily'].values())[-3:]):+.2f}. The small newly available temporal extension has {r['extension']['trades']} completed trades totaling ${r['extension']['net']:+.4f}; this is not a meaningful validation sample. Weekdays total ${b['weekday_net']:+.2f}; weekends ${b['weekend_net']:+.2f}. A weekday-only filter would be a new post-selection hypothesis, not an established improvement.",'',f"Exploratory independent-day bootstrap 95% interval for 15-day total: ${boot[500]:+.2f} to ${boot[19500]:+.2f}. This assumes independent representative days, does not address unseen regimes, and is unadjusted for selection. The prior 128-hypothesis audit gave gold reversal BH-adjusted p about 0.786. These new overlapping sensitivity checks do not create independent evidence.",'','## Product and operational feasibility','',f"Fresh public snapshot: active exchange and trading; best ask ${ask[0]:.4f} for {ask[1]:g} contracts, best bid ${bid[0]:.4f} for {bid[1]:g}. {count} whole contracts cost ${count*ask[0]:.4f} notional, within $50; snapshot top-of-book size covers both sides. This confirms current small-size feasibility, not historical or future fills.",'','API contract_size is 0.001, quote about $4.28 per contract; use API contract prices directly in dollar P&L (do not multiply by 0.001 a second time). Current market reports about $9.66m 24-hour notional volume. Maximum leverage estimate near 15x is not a target. A $100 account with <=$50 position notional should be modeled without leveraged exposure; actual isolated/cross collateral configuration and account entitlement must be checked before any implementation. No account-readiness claim is made from public market availability.','','The historical funding endpoint returns one gold record per day at 14:00 UTC across this sample (16 total through September 26). The simulation uses those actual records, not a generic assumed three-times-daily schedule. Account-level funding reconciliation remains a live-validation requirement. Fees are current account-rate scenarios, not historical fee reconstruction.','','A research prototype would freeze the original UTC schedule and $50 notional cap, record every signal/skip and contemporaneous depth, mark open P&L, reconcile funding, and use reduce-only exits with stale-data/outage handling. Its forward record must be kept separate from this reused history. At least 30 additional calendar days and 100 completed signals would be a first review point, not an automatic activation threshold. Positive after-cost performance in both halves, execution within modeled costs, complete accounting and a non-fragile timing result would be required before reconsidering live use. The $100 stays unallocated during this research stage.','','## Audit and provenance','',f"Reproduced the previous +$3.6859885372 result exactly; {len(errors)} errors checking notional limits, position overlap, signal/entry/exit ordering and P&L accounting. Source minute files reside in ../kalshi_full_review_2026_09_26/perps_data; current market/book/risk/status/hourly/funding responses are retained in data/. Hourly availability begins September 10; no longer Kalshi gold-perpetual history was obtained by requesting September 1 onward. Spot/futures history cannot establish historical Kalshi spreads or fills.",'','- [Kalshi market API](https://docs.kalshi.com/margin-rest/market/get-market)','- [Historical funding API](https://docs.kalshi.com/margin-rest/funding/get-historical-funding-rates)','- [Fees explanation](https://help.kalshi.com/en/articles/16071417-perps-fees-explained)','- [Margin explanation](https://help.kalshi.com/en/articles/15357594-how-margin-works)']
(P/'REPORT.md').write_text('\n'.join(lines)+'\n');print(json.dumps(v,indent=2))
